/**
 * Mock service driving the fixed-duration path: a single value in
 * `sessionDurations`, no `durationRange`. Drives `Service.DurationInMinutes`;
 * `Service.DurationRange` renders nothing for this shape.
 *
 * `mockService` already carries this shape — this is a renamed copy for
 * tests/examples that want to name the case they're exercising.
 */
export const mockServiceFixedDuration = {
    ...mockService,
    _id: 'test-service-fixed-duration',
    name: 'Fixed Duration Service',
    schedule: {
        availabilityConstraints: {
            sessionDurations: [60],
        },
    },
};
/**
 * Mock service driving the HOUR-unit DurationRange path. Mirrors the server
 * payload shape: empty `sessionDurations`, range pre-computed at
 * `availabilityConstraints.durationRange`. `durationRange` is not yet in the
 * SDK's `AvailabilityConstraints` typing (runtime is ahead of types), so the
 * service object is cast — matches the read-side cast in
 * `core/service/Service.tsx`.
 */
export const mockServiceHourRange = {
    ...mockService,
    _id: 'test-service-hour-range',
    name: 'Hourly Range Service',
    schedule: {
        availabilityConstraints: {
            sessionDurations: [],
            durationRange: {
                unitType: 'HOUR',
                hourOptions: {
                    minDurationInMinutes: 120,
                    maxDurationInMinutes: 540,
                },
            },
        },
    },
};
/**
 * Mock service driving the DAY-unit DurationRange path. Same server shape as
 * {@link mockServiceHourRange}.
 */
export const mockServiceDayRange = {
    ...mockService,
    _id: 'test-service-day-range',
    name: 'Daily Range Service',
    schedule: {
        availabilityConstraints: {
            sessionDurations: [],
            durationRange: {
                unitType: 'DAY',
                dayOptions: {
                    minDurationInDays: 2,
                    maxDurationInDays: 5,
                },
            },
        },
    },
};
